def main():
	(n, m) = read()
	matrix = [read() for _ in range(n)]
	mod = 10 ** 11
	for i in range(n - 1):
		poss = set()
		for j in range(m):
			poss.add(matrix[i + 1][j] - matrix[i][j])
		if len(poss) > 2:
			return 'NO'
		if len(poss) == 2 and mod != 10 ** 11 and (mod != max(poss) - min(poss)):
			return 'NO'
		if len(poss) == 2:
			mod = max(poss) - min(poss)
	if mod <= max((max(matrix[i]) for i in range(n))):
		return 'NO'
	print('YES')
	print(mod)
	write([(matrix[i][0] - matrix[0][0]) % mod for i in range(n)])
	print()
	write(matrix[0])

def read(mode=2):
	inputs = input().strip()
	if mode == 0:
		return inputs
	if mode == 1:
		return inputs.split()
	if mode == 2:
		return list(map(int, inputs.split()))

def write(s='\n'):
	if s is None:
		s = ''
	if isinstance(s, list):
		s = ' '.join(map(str, s))
	s = str(s)
	print(s, end='')
